  "questSkills": [
    {"id":"novice-first-aid","name":"First Aid","class":"Novice","instructions":"First acquire 3 Clovers and 3 Red Herbs. Go to the inn west of the fountain in Prontera. Talk to the NPC there to learn about the skill. She mentions you'll need a Clean Guaze. Go to Prontera castle, and then upstairs on the east side. Find the nurse and get the Gauze. Return to the NPC at the inn and get the skill.","source":[858,876]},
    {"id":"novice-play-dead","name":"Play Dead","class":"Novice","instructions":"Talk to the NPC in the Knight's Guild about the skill. Go back to the nurse NPC in Prontera castle and you'll get a Novice Card. Return to the NPC in the Knight Guild.","source":[877,962]},
    {"id":"swordsman-auto-berserk","name":"Auto Berserk","class":"Swordsman","instructions":"Acquire 35 Powder of Butterfly, 10 Honey, 10 Horrendous Mouths, and 10 Decayed Nails","source":[1325,1339]},
    {"id":"swordsman-fatal-blow","name":"Fatal Blow","class":"Swordsman","instructions":"First get 10 Fire Arrows, 10 Silver Arrows, 10 Banana Juice, 30 Tentacles, and 5 Royal Jelly. Then go into one of the side rooms at the Prontera Upgrade NPC and talk to the NPC there.","source":[1340,1356]},
    {"id":"swordsman-walking-hp-recovery","name":"Walking HP Recovery","class":"Swordsman","instructions":"This one is a pain. You need a whopping 500 Empty Bottles, 1 Padded Armor, and a Rocker Doll. Go to Izlude, and enter a building in the northeast. Talk to the NPC there to get it.","source":[1357,1376]},
    {"id":"thief-back-slide","name":"Back Slide","class":"Thief","instructions":"First get 20 Grasshopper Legs. Then go to the Thieves Guild in the Pyramids. Enter the room on the right and talk to the NPC.","source":[2475,2487]},
    {"id":"thief-find-stone","name":"Find Stone","class":"Thief","instructions":"Acquire 1 Bear's Footskin, 1 Zargon, and 5 Spawn. Go to the same location as the previous NPC to get the skill.","source":[2488,2501]},
    {"id":"thief-stone-fling","name":"Stone Fling","class":"Thief","instructions":"2 Garlet and 2 Scell are all that are needed. Go to the same place as the other NPCs to get the skill.","source":[2502,2515]},
    {"id":"thief-sand-attack","name":"Sand Attack","class":"Thief","instructions":"Get 5 Fine Grits, 1 Cobweb, 1 Snail's Shell, 1 Cactus Needle, 1 Earthworm Peeling. Go to the same place as the other quests. Talk to the NPC. He will take your 5 Fine Grits and tell you to go to Payon. Go to the west side of town and find the NPC. Give him the other items, then go back to the NPC in the Pyramids to get the skill.","source":[2516,2538]},
    {"id":"archer-arrow-crafting","name":"Arrow Crafting","class":"Archer","instructions":"Obtain 1 Red Potion, 20 Resin, 13 Trunk, 41 Tough Scalelike Stem, and 7 Mushroom Spore. Go to the south square in Morroc, and walk a bit northwest. Talk to the NPC there to get the skill.","source":[3585,3690]},
    {"id":"archer-arrow-repel","name":"Arrow Repel","class":"Archer","instructions":"Obtain 1 Crossbow, 10 Tentacles, 10 Bill of Birds, 3 Yoyo Tail, 2 Emerald, 36 Banana Juice. Go to Payon, and go behind a house in the lower left corner to find the NPC.","source":[3691,3713]},
    {"id":"magician-energy-coat","name":"Energy Coat","class":"Magician","instructions":"Obtain 3 Glass Beads, 1 1 Karat Diamond, 5 Shells, 1 Solid Shell. Go to the NPC in the Geffen Mage Guild to obtain the skill.","source":[5067,5093]},
    {"id":"acolyte-holy-light","name":"Holy Light","class":"Acolyte","instructions":"Acquire an Opal, Crystal Blue, and Rosary. Go to the Acolyte NPC in the East Wing of the Prontera Church, the same place you changed jobs.","source":[6295,6313]},
    {"id":"merchant-crazy-uproar","name":"Crazy Uproar","class":"Merchant","instructions":"Obtain 7 Pearl, 50 Mushroom Spore, and 1 Banana Juice. Head to Alberta, and talk to a NPC a bit east of the Merchant Guild.","source":[7461,7475]},
    {"id":"merchant-change-cart","name":"Change Cart","class":"Merchant","instructions":"Obtain 50 Trunk, 10 Iron, and 20 Animal Skin. Talk to a NPC in the north of Alberta, east from the large house.","source":[7476,7492]},
    {"id":"merchant-cart-revolution","name":"Cart Revolution","class":"Merchant","instructions":"Get 30 Iron, 30 Sticky Mucus, 20 Fly Wing, 5 Tentacle, and 2 Grape Juice. Go to the ship in Alberta, and head to the east along the docks. Talk to the NPC there to get the skill.","source":[7493,7512]}
  ],
